# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KALITSAL VE KAZANILMIŞ (ŞARTLI) REFLEKSLERİN KARŞILAŞTIRILMASI</text>\n  <rect x="25" y="48" width="310" height="182" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="74" text-anchor="middle" font-size="13.5" font-weight="bold" fill="#1e40af">1. Kalıtsal (Doğuştan) Refleksler</text>\n  <text x="40" y="100" font-size="11" fill="#334155">• Türe özgüdür, doğuştan hazır bulunur.</text>\n  <text x="40" y="122" font-size="11" fill="#334155">• Öğrenme gerektirmez ve unutulmaz.</text>\n  <text x="40" y="144" font-size="11" fill="#334155">• Doğrudan omurilik, orta beyin veya</text>\n  <text x="48" y="160" font-size="11" fill="#334155">omurilik soğanı tarafından yönetilir.</text>\n  <rect x="42" y="174" width="276" height="42" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.2"/>\n  <text x="180" y="192" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">Örnek: Emme refleksi, diz kapağı refleksi,</text>\n  <text x="180" y="207" text-anchor="middle" font-size="10.5" fill="#1d4ed8">göz bebeği refleksi, sıcak cisimden el çekme</text>\n\n  <rect x="365" y="48" width="310" height="182" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="74" text-anchor="middle" font-size="13.5" font-weight="bold" fill="#166534">2. Kazanılmış (Şartlı) Refleksler</text>\n  <text x="380" y="100" font-size="11" fill="#334155">• Deneyim ve tekrarlarla sonradan kazanılır.</text>\n  <text x="380" y="122" font-size="11" fill="#334155">• Uzun süre tekrarlanmazsa zayıflayabilir.</text>\n  <text x="380" y="144" font-size="11" fill="#334155">• Önce beyin kabuğu (uç beyin) öğrenir,</text>\n  <text x="388" y="160" font-size="11" fill="#334155">sonra kontrol omuriliğe devredilir.</text>\n  <rect x="382" y="174" width="276" height="42" rx="6" fill="#ffffff" stroke="#22c55e" stroke-width="1.2"/>\n  <text x="520" y="192" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">Örnek: Yüzmek, bisiklet sürmek, dans etmek,</text>\n  <text x="520" y="207" text-anchor="middle" font-size="10.5" fill="#15803d">limon görünce ağzın sulanması</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">REFLEKS YAYI BASAMAKLARI (ÜÇ NÖRONLU VE İKİ NÖRONLU MODEL)</text>\n  <rect x="20" y="45" width="660" height="105" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">A) ÜÇ NÖRONLU REFLEKS YAYI (Örn: Sıcak Cisimden veya İğneden Eli Çekme)</text>\n  <rect x="32" y="80" width="85" height="52" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="74" y="102" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">1. Reseptör</text>\n  <text x="74" y="118" text-anchor="middle" font-size="9.5" fill="#334155">(Deri Almacı)</text>\n  <text x="125" y="110" text-anchor="middle" font-size="13" font-weight="bold" fill="#d97706">→</text>\n  <rect x="134" y="80" width="95" height="52" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="181" y="102" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">2. Duyu Nöronu</text>\n  <text x="181" y="118" text-anchor="middle" font-size="9.5" fill="#334155">(Arka Kök Girişi)</text>\n  <text x="237" y="110" text-anchor="middle" font-size="13" font-weight="bold" fill="#d97706">→</text>\n  <rect x="246" y="80" width="110" height="52" rx="6" fill="#fde68a" stroke="#d97706" stroke-width="1.8"/>\n  <text x="301" y="102" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#78350f">3. Ara Nöron</text>\n  <text x="301" y="118" text-anchor="middle" font-size="9.5" fill="#78350f">(Omurilik Boz Madde)</text>\n  <text x="365" y="110" text-anchor="middle" font-size="13" font-weight="bold" fill="#d97706">→</text>\n  <rect x="374" y="80" width="98" height="52" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="423" y="102" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">4. Motor Nöron</text>\n  <text x="423" y="118" text-anchor="middle" font-size="9.5" fill="#334155">(Ön Kök Çıkışı)</text>\n  <text x="481" y="110" text-anchor="middle" font-size="13" font-weight="bold" fill="#d97706">→</text>\n  <rect x="490" y="80" width="85" height="52" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="532" y="102" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">5. Efektör</text>\n  <text x="532" y="118" text-anchor="middle" font-size="9.5" fill="#334155">(Kol Kası)</text>\n  <text x="584" y="110" text-anchor="middle" font-size="13" font-weight="bold" fill="#d97706">→</text>\n  <rect x="592" y="80" width="76" height="52" rx="6" fill="#dcfce7" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="630" y="102" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">6. Tepki</text>\n  <text x="630" y="118" text-anchor="middle" font-size="9.5" fill="#166534">(El Çekilir)</text>\n\n  <rect x="20" y="162" width="660" height="82" rx="10" fill="#ede9fe" stroke="#7c3aed" stroke-width="2"/>\n  <text x="350" y="184" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#5b21b6">B) İKİ NÖRONLU BASİT REFLEKS YAYI (Diz Kapağı / Patella Refleksi)</text>\n  <text x="350" y="210" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#4c1d95">Tendon Reseptörü → Duyu Nöronu (Arka Kök) → [ARA NÖRON YOK / Tek Sinaps] → Motor Nöron (Ön Kök) → Ön Uyluk Kası</text>\n  <text x="350" y="230" text-anchor="middle" font-size="10.5" fill="#334155">Not: Duyu nöronu omurilik boz maddesinde doğrudan motor nöronla sinaps yapar; en hızlı refleks yayını oluşturur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HOMEOSTASİDE ANTAGONİST (ZIT ÇALIŞAN) HORMON ÇİFTLERİ</text>\n  <rect x="25" y="46" width="310" height="194" rx="10" fill="#e0f2fe" stroke="#0284c7" stroke-width="2"/>\n  <text x="180" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#0369a1">1. Kalsiyum (Ca²⁺) Dengesi</text>\n  <rect x="40" y="84" width="280" height="65" rx="6" fill="#ffffff" stroke="#38bdf8" stroke-width="1.5"/>\n  <text x="180" y="104" text-anchor="middle" font-size="11" font-weight="bold" fill="#0284c7">Kalsitonin (Tiroit Bezi)</text>\n  <text x="180" y="122" text-anchor="middle" font-size="10" fill="#334155">Kandaki fazla kalsiyumu kemiklere geçirir;</text>\n  <text x="180" y="137" text-anchor="middle" font-size="10" fill="#334155">böbreklerden Ca²⁺ geri emilimini azaltır.</text>\n  <rect x="40" y="158" width="280" height="68" rx="6" fill="#ffffff" stroke="#38bdf8" stroke-width="1.5"/>\n  <text x="180" y="178" text-anchor="middle" font-size="11" font-weight="bold" fill="#0369a1">Parathormon (Paratiroit Bezi)</text>\n  <text x="180" y="196" text-anchor="middle" font-size="10" fill="#334155">Kemikten kana kalsiyum geçişini ve</text>\n  <text x="180" y="211" text-anchor="middle" font-size="10" fill="#334155">böbrek/bağırsaktan Ca²⁺ emilimini artırır.</text>\n\n  <rect x="365" y="46" width="310" height="194" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Kan Şekeri (Glikoz) Dengesi</text>\n  <rect x="380" y="84" width="280" height="65" rx="6" fill="#ffffff" stroke="#4ade80" stroke-width="1.5"/>\n  <text x="520" y="104" text-anchor="middle" font-size="11" font-weight="bold" fill="#16a34a">İnsülin (Pankreas Beta Hücreleri)</text>\n  <text x="520" y="122" text-anchor="middle" font-size="10" fill="#334155">Yüksek kan glikozunu hücrelere sokar;</text>\n  <text x="520" y="137" text-anchor="middle" font-size="10" fill="#334155">karaciğerde glikojen depolanmasını sağlar.</text>\n  <rect x="380" y="158" width="280" height="68" rx="6" fill="#ffffff" stroke="#4ade80" stroke-width="1.5"/>\n  <text x="520" y="178" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Glukagon (Pankreas Alfa Hücreleri)</text>\n  <text x="520" y="196" text-anchor="middle" font-size="10" fill="#334155">Açlıkta karaciğerdeki glikojeni glikoza</text>\n  <text x="520" y="211" text-anchor="middle" font-size="10" fill="#334155">yıkarak kan şekerini normale yükseltir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
